nodes.body:
{
  "artifactKind": "design concept",
  "audience": "The team and its agents deciding what a physical product will be before parts are chosen; customers once a revision is announced.",
  "purpose": "Record, as images, what we think the product will look like at each revision, so a product visibly evolves from rough ideas to a real device.",
  "outputTitle": "Design concept",
  "sections": [
    "Subject",
    "Images",
    "What this is not"
  ],
  "sourceScope": "One ProductRevision in its own Wiki. The output is a Document whose body is JSON: subject {id, revision} pinning the revision, and images, a list of {artifact, prompt, model, createdAt, caption} for each generated or drawn mockup, where artifact cites the image file in the shared evidence shape (provider, recordId, uri, contentHash). Link the Document to the revision with evidence_for and documents.",
  "refreshPolicy": "Never rewrite a published concept; a new set of images for the same revision is a new Document, so the sequence of concepts stays visible.",
  "revisionPolicy": "Each Document pins the revision's graph record revision in its subject; the prompt and model of every image are kept so the picture can be regenerated or compared.",
  "status": "proposed",
  "sectionMappings": [
    {
      "title": "Subject",
      "types": [
        "ProductRevision"
      ],
      "mode": "links"
    },
    {
      "title": "Images",
      "types": [
        "Document"
      ],
      "mode": "fields",
      "fields": [
        "images"
      ]
    }
  ]
}
